@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#f2eee4;--muted:#a9aaa0;--dim:#777d75;--lime:#d9f36a;--orange:#f5a751;--panel:rgba(17,23,21,.86);--line:rgba(236,232,216,.15)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#171d19;color:var(--ink);font-family:Manrope,system-ui,sans-serif}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#1a211c;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,13,12,.54),transparent 25%,transparent 68%,rgba(7,11,10,.5)),linear-gradient(90deg,rgba(6,10,9,.24),transparent 45%,rgba(6,10,9,.15);z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:82px;padding:17px 30px;display:flex;align-items:center;gap:28px;background:linear-gradient(180deg,rgba(10,15,14,.86),rgba(10,15,14,.52));border-bottom:1px solid rgba(255,255,255,.09)}.brand{display:flex;align-items:center;gap:11px;min-width:247px}.brand-mark{width:37px;height:37px;border:1px solid var(--lime);color:var(--lime);display:grid;place-items:center;font:800 13px 'Barlow Condensed';letter-spacing:-.7px;transform:skew(-8deg)}.brand strong{display:block;font:800 17px 'Barlow Condensed';letter-spacing:1.35px}.brand small,.district small,.wallet small{display:block;color:#a6aaa0;font:10px 'DM Mono',monospace;letter-spacing:1.4px;margin-top:3px}.district{margin-left:auto;display:flex;align-items:center;gap:10px}.live-dot{width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 12px var(--lime)}.district strong,.wallet strong{font:700 12px 'DM Mono',monospace;letter-spacing:.5px}.wallet{display:flex;align-items:center;gap:8px;padding:0 22px;border-left:1px solid var(--line);border-right:1px solid var(--line)}.wallet-icon{color:var(--lime);font-size:14px}.heat{width:142px}.heat-label{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;letter-spacing:.7px;color:#b8bbb1}.heat-label strong{color:var(--lime);font-weight:500}.heat-pips{display:flex;gap:4px;margin-top:7px}.heat-pips i{display:block;height:4px;flex:1;background:rgba(255,255,255,.17);border-radius:2px}.heat-pips i.hot{background:#ff675b;box-shadow:0 0 7px rgba(255,75,60,.55)}
.mission-panel{position:absolute;z-index:3;left:30px;top:110px;width:330px;padding:17px 18px 16px;background:linear-gradient(135deg,rgba(14,20,18,.92),rgba(20,27,24,.76));border:1px solid var(--line);box-shadow:0 16px 35px #0b100f55;backdrop-filter:blur(8px)}.mission-kicker{display:flex;align-items:center;gap:8px;color:#c5c6b8;font:10px 'DM Mono',monospace;letter-spacing:1px}.mission-icon{font-size:14px;color:var(--lime)}.mission-status{margin-left:auto;color:var(--lime);font-size:9px}.mission-panel h1{font:700 23px 'Barlow Condensed',sans-serif;letter-spacing:.3px;margin:12px 0 3px}.mission-panel p{font-size:11px;line-height:1.6;color:#b5b7ad;margin:0 0 15px;max-width:275px}.mission-progress{display:none;align-items:center;gap:9px;margin:0 0 15px}.mission-progress.visible{display:flex}.progress-track{height:3px;background:#ffffff25;flex:1}.progress-track i{height:100%;width:0;display:block;background:var(--lime);transition:width .25s}.mission-progress span{white-space:nowrap;color:#c3c6b9;font:8px 'DM Mono',monospace;letter-spacing:.5px}.job-actions{display:grid;gap:7px}.job-button{height:50px;width:100%;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.045);display:flex;align-items:center;text-align:left;gap:10px;padding:0 10px;cursor:pointer;transition:.18s}.job-button:hover{background:rgba(217,243,106,.12);border-color:#d9f36a80;transform:translateX(2px)}.job-button.heist:hover{background:rgba(245,167,81,.12);border-color:#f5a75180}.job-symbol{width:28px;height:28px;display:grid;place-items:center;font-size:17px;color:var(--lime);background:#d9f36a12}.heist .job-symbol{color:var(--orange);background:#f5a75112}.job-button b{display:block;font:700 11px 'Barlow Condensed';letter-spacing:.8px}.job-button small{display:block;color:#a5a89e;font-size:9px;margin-top:2px}.job-arrow{margin-left:auto;color:#b9c176;font-size:16px}.toast{position:absolute;z-index:5;top:102px;left:50%;transform:translate(-50%,-12px);opacity:0;pointer-events:none;background:#d9f36a;color:#1c2419;padding:10px 18px;font:700 11px 'DM Mono',monospace;letter-spacing:.7px;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.event-banner{position:absolute;z-index:4;top:104px;left:50%;transform:translateX(-50%);color:var(--lime);text-align:center;text-shadow:0 2px 6px #000;pointer-events:none;font:700 12px 'DM Mono',monospace;letter-spacing:1px}.route-tip{position:absolute;z-index:3;display:none;left:50%;top:61%;transform:translate(-50%,-50%);align-items:center;gap:8px;color:#fff;text-shadow:0 1px 5px #000;font:700 10px 'DM Mono',monospace;letter-spacing:.8px;white-space:nowrap}.route-tip.visible{display:flex}.keycap{display:grid;place-items:center;width:25px;height:24px;color:#1b211a;background:var(--lime);font-size:13px;border-radius:2px;box-shadow:0 3px 12px #0008}
.map-frame{position:absolute;z-index:3;left:30px;bottom:24px;width:188px;padding:8px 8px 6px;background:rgba(14,19,17,.83);border:1px solid var(--line);box-shadow:0 9px 22px #0005}.map-heading{display:flex;justify-content:space-between;padding:1px 3px 5px;color:#b6b9ad;font:8px 'DM Mono',monospace;letter-spacing:1px}.map-compass{color:#d9f36a}.map-frame canvas{display:block;width:170px;height:130px;object-fit:fill;opacity:.94;background:#26312b}.map-legend{display:flex;align-items:center;gap:5px;padding:5px 3px 0;color:#aeb2a7;font:8px 'DM Mono',monospace;letter-spacing:.5px}.map-legend i{width:6px;height:6px;border-radius:50%;background:#d9f36a;box-shadow:0 0 5px #d9f36a}.map-legend span{margin-left:auto;color:#f5a751}.speed-card{position:absolute;z-index:3;right:30px;bottom:25px;width:192px;padding:12px 14px 11px;background:rgba(14,19,17,.85);border:1px solid var(--line);box-shadow:0 9px 22px #0005}.speed-top{display:flex;justify-content:space-between;color:#aeb2a7;font:9px 'DM Mono',monospace;letter-spacing:1px}.gear{color:var(--lime)}.speed-value{font:700 50px/.95 'Barlow Condensed';letter-spacing:1px;color:#f1eee4;margin:5px 0 8px}.speed-track{height:3px;background:#ffffff24}.speed-track i{height:100%;display:block;width:0;background:linear-gradient(90deg,#d9f36a,#f5a751);transition:width .15s}.speed-footer{display:flex;justify-content:space-between;margin-top:9px;color:#aeb2a7;font:8px 'DM Mono',monospace;letter-spacing:.5px}.nitro-label b{color:var(--lime);font-weight:500}.nitro-label b.empty{color:#888}.controls-hint{position:absolute;z-index:3;left:50%;bottom:22px;transform:translateX(-50%);display:flex;gap:17px;white-space:nowrap;color:#d0d1c7;font:8px 'DM Mono',monospace;letter-spacing:.4px;text-shadow:0 1px 3px #000}.controls-hint span{display:flex;align-items:center;gap:4px}kbd{font:8px 'DM Mono',monospace;padding:3px 4px;border:1px solid #ffffff55;background:#111a;color:#fff;border-radius:2px}.touch-controls{display:none;position:absolute;z-index:4;left:15px;right:15px;bottom:18px;justify-content:space-between;align-items:flex-end;pointer-events:none}.touch-steer,.touch-pedals{display:flex;gap:8px}.touch-controls button{pointer-events:auto;border:1px solid #ffffff44;background:#141a19bb;color:#f3f0e5;width:52px;height:52px;border-radius:50%;font-size:18px;backdrop-filter:blur(5px);touch-action:none}.touch-controls button:active,.touch-controls button.down{background:#d9f36a;color:#182014}.touch-controls .touch-nitro{width:48px;height:48px;border-color:#d9f36a80;color:var(--lime);font:700 11px 'DM Mono',monospace;align-self:center}
.intro{position:absolute;z-index:10;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(9,13,12,.73),rgba(9,13,12,.26) 70%,rgba(9,13,12,.42));transition:opacity .55s,visibility .55s}.intro.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-card{width:min(475px,calc(100vw - 32px));margin-left: min(27vw,350px);padding:26px 30px 20px;background:rgba(14,19,17,.94);border:1px solid rgba(233,230,214,.19);box-shadow:0 24px 80px #0008;backdrop-filter:blur(12px);position:relative}.intro-card:before{content:'';position:absolute;left:-1px;top:28px;width:3px;height:67px;background:var(--lime);box-shadow:0 0 16px #d9f36a80}.intro-eyebrow{display:flex;align-items:center;gap:8px;color:#b7baad;font:8px 'DM Mono',monospace;letter-spacing:1.1px}.intro-eyebrow span{width:4px;height:4px;background:var(--orange);transform:rotate(45deg)}.intro-title{font:900 57px/.82 'Barlow Condensed',sans-serif;letter-spacing:-1px;margin-top:22px;text-shadow:3px 4px 0 #0008}.intro-title em{color:var(--lime);font-style:normal}.intro-title sup{font:500 10px 'DM Mono';vertical-align:top;margin-left:4px;color:#aeb2a7}.intro-sub{color:var(--orange);font:9px 'DM Mono',monospace;letter-spacing:1.1px;margin:14px 0 17px}.intro-rule{height:1px;background:linear-gradient(90deg,#d9f36a88,transparent);width:100%}.intro-copy{font-size:11px;line-height:1.8;color:#c1c3ba;margin:14px 0 17px}.intro-jobs{display:grid;gap:8px}.intro-jobs button{width:100%;display:flex;align-items:center;gap:11px;text-align:left;padding:9px 11px;background:#ffffff08;border:1px solid #ffffff20;cursor:pointer;transition:.2s}.intro-jobs button:first-child:hover{border-color:#d9f36a99;background:#d9f36a12}.intro-jobs button:last-child:hover{border-color:#f5a75199;background:#f5a75112}.intro-job-icon{width:30px;height:30px;display:grid;place-items:center;background:#d9f36a15;color:var(--lime);font-size:18px}.intro-jobs button:last-child .intro-job-icon{color:var(--orange);background:#f5a75115}.intro-jobs b{display:block;font:700 11px 'Barlow Condensed';letter-spacing:.7px}.intro-jobs small{display:block;color:#aeb1a6;font-size:9px;margin-top:2px}.intro-go{margin-left:auto;color:var(--lime);font-size:17px}.intro-foot{display:flex;justify-content:space-between;gap:8px;margin-top:16px;color:#8f948b;font:7px 'DM Mono',monospace;letter-spacing:.3px}.intro-caption{position:absolute;bottom:21px;left:30px;color:#a7aa9e;font:8px 'DM Mono',monospace;letter-spacing:1px}.intro-caption span{color:var(--lime);margin-left:8px}.fade-layer{position:absolute;inset:0;z-index:9;background:#080d0c;opacity:0;pointer-events:none;transition:opacity .25s}.fade-layer.active{opacity:.82}
@media(max-width:850px){.topbar{height:67px;padding:12px 16px;gap:14px}.brand{min-width:unset}.brand strong{font-size:15px}.brand-mark{width:32px;height:32px}.district{display:none}.wallet{margin-left:auto;padding:0 12px}.mission-panel{top:82px;left:16px;width:275px;padding:13px}.mission-panel h1{font-size:20px;margin-top:8px}.mission-panel p{font-size:10px;margin-bottom:10px}.job-button{height:44px}.map-frame{left:16px;bottom:15px;width:150px;padding:6px}.map-frame canvas{width:136px;height:100px}.speed-card{right:16px;bottom:15px;width:150px;padding:9px 11px}.speed-value{font-size:41px}.controls-hint{bottom:15px;gap:9px;font-size:7px}.intro-card{margin-left:25vw}.intro-caption{left:16px}}
@media(max-width:600px){#game{min-height:420px}.topbar{padding:10px 12px;height:58px}.brand strong{font-size:13px;letter-spacing:.8px}.brand small{font-size:8px}.brand-mark{width:28px;height:28px;font-size:11px}.wallet{padding:0 0 0 11px;border-right:0}.wallet small{font-size:8px}.wallet strong{font-size:10px}.heat{width:95px}.heat-label{font-size:7px}.mission-panel{top:69px;left:10px;width:232px;padding:10px}.mission-kicker{font-size:8px}.mission-panel h1{font-size:18px;margin:7px 0 2px}.mission-panel p{font-size:9px;line-height:1.45;margin-bottom:8px}.job-button{height:38px;gap:7px;padding:0 7px}.job-symbol{width:24px;height:24px}.job-button b{font-size:10px}.job-button small{font-size:8px}.mission-progress{margin-bottom:9px}.map-frame{left:10px;bottom:12px;width:112px}.map-frame canvas{width:98px;height:78px}.map-heading{font-size:7px}.map-legend{font-size:6px}.speed-card{right:10px;bottom:12px;width:119px;padding:8px}.speed-value{font-size:35px;margin:3px 0 6px}.speed-footer{font-size:6px}.speed-top{font-size:7px}.controls-hint{display:none}.touch-controls{display:flex}.intro{background:rgba(7,11,10,.6);align-items:center}.intro-card{margin:0;padding:20px 20px 15px;width:min(390px,calc(100vw - 28px))}.intro-title{font-size:48px;margin-top:17px}.intro-copy{font-size:10px;margin:11px 0 13px}.intro-sub{font-size:8px;margin:11px 0 14px}.intro-foot{font-size:6px;margin-top:12px}.intro-caption{bottom:7px;left:50%;transform:translateX(-50%);width:100%;text-align:center;font-size:6px;white-space:nowrap}.intro-caption span{margin-left:4px}.event-banner{top:70px;font-size:9px}.toast{top:64px;font-size:9px}.route-tip{top:62%;font-size:9px}}
@media(max-height:600px) and (min-width:601px){.mission-panel{top:88px;padding:11px 14px}.mission-panel h1{margin-top:7px}.mission-panel p{margin-bottom:8px}.job-button{height:40px}.map-frame,.speed-card,.controls-hint{bottom:10px}.intro-card{padding:18px 24px}.intro-title{font-size:49px;margin-top:14px}.intro-copy{margin:10px 0}}

