    }else if(p.kind==='square'){
      ctx.fillStyle='#8f8871';ctx.fillRect(x-56*s,y-42*s,112*s,84*s);
      ctx.fillStyle='#aaa082';ctx.fillRect(x-48*s,y-34*s,96*s,68*s);
